"use client";
import { GlowButton, GlowPill } from "@/components/application/selene/glow-pill";

const stage = { display: "flex", alignItems: "center", justifyContent: "center", gap: 12, width: "100%", minHeight: 320, padding: 32, background: "#000" } as const;

export default function GlowPillDemo({ variant = "prompt" }: { variant?: string }) {
  if (variant === "badge")
    return (
      <div style={stage}>
        <GlowPill phrases={["Now live."]} width={240} />
      </div>
    );
  if (variant === "button")
    return (
      <div style={stage}>
        <GlowButton>Ask the assistant</GlowButton>
        <button type="button" style={{ height: 36, padding: "0 16px", border: 0, borderRadius: 9999, background: "#1c1c1e", color: "#d4d4d8", font: "inherit", fontSize: 13, fontWeight: 500, cursor: "pointer" }}>
          Later
        </button>
      </div>
    );
  return (
    <div style={stage}>
      <GlowPill phrases={["Ask anything.", "More personal.", "More powerful."]} width={300} />
    </div>
  );
}

