"use client";
/**
 * Glow Pill: a black glass stadium with light pooled along its bottom edge.
 * It types through a list of phrases, and every swap sends a surge of colour
 * up the glass. One WebGL pass draws the glass, the light and the text; a CSS
 * stand-in takes over where WebGL is unavailable. Made for black surfaces.
 */
import { useEffect, useRef, useState, type ButtonHTMLAttributes, type CSSProperties, type ReactNode } from "react";

export interface GlowColors {
  /** The light on the left of the pool. */
  warm: string;
  /** The white sun at the centre of the edge. */
  core: string;
  /** The tone between the two sides. */
  mid: string;
  /** The light on the right of the pool. */
  cool: string;
}

export const GLOW_PALETTES = {
  aurora: { warm: "#8f5f50", core: "#ffffff", mid: "#5f7a6c", cool: "#4a5a96" },
  ember: { warm: "#b4532a", core: "#fff2e2", mid: "#9a4a3c", cool: "#6c3358" },
  ice: { warm: "#5a86a8", core: "#f3fbff", mid: "#4f8f96", cool: "#3c4f9c" },
} satisfies Record<string, GlowColors>;

export type GlowPaletteName = keyof typeof GLOW_PALETTES;

export const GLOW_TIMING = { startDelay: 600, typeSpeed: 53, hold: 744 };

const VERTEX = `
attribute vec2 aPos;
varying vec2 vUv;
void main() {
  vUv = aPos * 0.5 + 0.5;
  gl_Position = vec4(aPos, 0.0, 1.0);
}
`;

const FRAGMENT = `
precision highp float;
uniform vec2 uRes;
uniform float uPad;
uniform float uTime;
uniform float uSurge;
uniform float uFront;
uniform float uGlow;
uniform float uButton;
uniform vec3 uWarm;
uniform vec3 uCore;
uniform vec3 uMid;
uniform vec3 uCool;
uniform sampler2D uText;
varying vec2 vUv;

float stadium(vec2 p, float aspect) {
  return length(vec2(max(abs(p.x) - 0.5 * (aspect - 1.0), 0.0), p.y)) - 0.5;
}

float rand(float n) { return fract(sin(n * 91.345) * 47453.13); }

/* Warm on the left, the mid tone softened by the core, cool on the right. */
vec3 tone(float x) {
  vec3 mid = mix(uMid, uCore, 0.3);
  vec3 c = mix(uWarm, mid, smoothstep(-1.2, 0.0, x));
  return mix(c, uCool, smoothstep(0.05, 1.25, x));
}

void main() {
  vec2 frag = vUv * uRes;
  float h = uRes.y - 2.0 * uPad;
  float aspect = (uRes.x - 2.0 * uPad) / h;
  float px = 1.0 / h;
  vec2 p = (frag - 0.5 * uRes) / h;
  float t = uTime;
  float btn = uButton;

  float d = stadium(p, aspect);
  float inside = 1.0 - smoothstep(-1.5 * px, 0.0, d);
  vec2 edge = vec2(max(abs(p.x) - 0.5 * (aspect - 1.0), 0.0) * sign(p.x), p.y);
  vec2 normal = edge / max(length(edge), 1e-4);

  /* Light is laid out for a 2.9:1 pill; wider shapes spread it sideways. */
  float x = p.x / max(aspect / 2.9, 0.55);
  float y = p.y + 0.5;

  /* The pool's surface rolls slowly, like liquid under the glass. */
  float swell = 0.02 * sin(x * 2.4 + t * 0.9) + 0.012 * sin(x * 4.1 - t * 1.3 + 2.0) + 0.007 * sin(x * 7.0 + t * 1.9);
  float yy = max(y - swell * (1.0 + 0.6 * uSurge), 0.0);

  vec3 light = vec3(0.0);
  for (int i = 0; i < 7; i++) {
    float fi = float(i);
    float a = rand(fi + 1.0), b = rand(fi + 11.0), c = rand(fi + 23.0);
    float home = -1.25 + fi * 0.417 + 0.1 * (a - 0.5);
    float lx = home + 0.12 * sin(t * (0.3 + 0.25 * a) + 6.2832 * b);
    float w = (0.24 + 0.14 * c) * (0.9 + 0.15 * sin(t * (0.45 + 0.3 * b) + fi));
    float lift = 0.75 + 0.45 * (0.5 + 0.5 * sin(t * (0.5 + 0.4 * c) + 6.2832 * a));
    float flare = pow(0.5 + 0.5 * sin(t * (0.6 + 0.35 * b) + fi * 2.1), 12.0);
    float tall = ((0.12 + 0.07 * a) * lift + 0.15 * flare) * mix(1.0, 1.5, btn);
    float dx = (x - lx) / (w * mix(1.0, 1.3, btn));
    vec3 col = tone(home + 0.4 * (b - 0.5)) * (0.8 + 0.4 * c);
    col = max(mix(vec3(dot(col, vec3(0.3333))), col, 1.0 + 0.5 * btn), 0.0);
    light += 0.32 * mix(1.0, 1.4, btn) * col * exp(-dx * dx) * exp(-pow(yy / tall, 1.5));
  }

  /* The sun: a bright core under the middle of the edge, breathing. */
  float sx = 0.03 * sin(t * 0.6) + 0.02 * sin(t * 1.1 + 2.0);
  float breath = 0.88 + 0.12 * sin(t * 1.05 + 1.4);
  float calm = (1.0 - 0.6 * uSurge) * breath;
  float lobe = (x - sx) / (0.32 + 0.03 * sin(t * 0.85));
  float halo = 0.95 * exp(-lobe * lobe);
  light += uCore * halo * calm * mix(1.35, 1.1, btn) * exp(-yy / (mix(0.1, 0.13, btn) * calm));
  light += uCore * halo * 0.08 * (1.0 - btn) * exp(-y / 0.8);

  /* Its horizon is crisp, and splits into a faint spectrum at the rim. */
  vec2 r = vec2(0.33 + 0.04 * breath, mix(0.075, 0.13, btn) * calm);
  float shift = mix(0.016, 0.032, btn);
  vec2 q = vec2(x - sx, y + 0.03);
  vec3 dome = vec3(
    smoothstep(1.0, 0.88, length((q - vec2(shift, 0.0)) / r)),
    smoothstep(1.0, 0.88, length(q / r)),
    smoothstep(1.0, 0.88, length((q + vec2(shift, 0.0)) / r)));
  light += uCore * dome;

  /* Surge: a wave of colour climbs from the core and washes the walls. */
  float reach = length(vec2(x / 2.2, y)) + 0.03 * sin(x * 3.0 - t * 2.4);
  float behind = uFront - reach;
  float band = exp(-pow(max(behind, 0.0) / 0.5, 2.0)) * smoothstep(-0.15, 0.05, behind);
  float wall = exp(d / 0.15);
  light += tone(x + 0.1 * sin(t * 1.2)) * (band * (0.6 + 0.4 * wall) + 0.1 * wall) * uSurge;

  light *= uGlow;

  /* Glass: a hairline rim, brightest along the top, catching the pool. */
  float line = exp(-pow(d / (1.2 * px + 0.0035), 2.0));
  float top = pow(max(normal.y, 0.0), 2.2);
  vec3 rim = vec3(mix(0.16 + 0.64 * top, 0.1 + 0.36 * top, btn)) + light * mix(0.35, 0.2, btn);
  float under = pow(max(-normal.y, 0.0), 1.5);
  rim += under * btn * (tone(x) * 0.9 + uCore * 0.5 * exp(-pow((x - sx) / 0.35, 2.0))) * uGlow;
  vec3 col = light + vec3(0.05 * top * exp(min(d, 0.0) / 0.022));

  /* Text sits behind the glass: pulled in at the edge, split by the surge. */
  vec2 tp = p / (1.0 + 0.04 * uSurge);
  tp += vec2(0.01 * sin(p.y * 9.0 + t * 7.0), 0.016 * sin(p.x * 4.5 - t * 6.0)) * uSurge;
  float lens = exp(min(d, 0.0) / 0.11);
  tp -= normal * lens * (0.012 + 0.05 * uSurge);
  float split = 0.007 * uSurge + 0.0012 * lens;
  vec2 o = vec2(split, 0.3 * split);
  vec4 tr = texture2D(uText, (tp + o) * h / uRes + 0.5);
  vec4 tg = texture2D(uText, tp * h / uRes + 0.5);
  vec4 tb = texture2D(uText, (tp - o) * h / uRes + 0.5);
  float ta = (tr.a + tg.a + tb.a) / 3.0;
  col = col * (1.0 - ta) + vec3(tr.r, tg.g, tb.b);

  col = clamp(col, 0.0, 1.0) * inside;
  col = clamp(col + clamp(rim, 0.0, 1.0) * line * 0.75, 0.0, 1.0);

  /* Buttons spill a soft bloom onto the page below them. */
  float border = min(min(frag.x, uRes.x - frag.x), min(frag.y, uRes.y - frag.y));
  vec3 bloom = (tone(x) * 0.55 + uCore * 0.6 * exp(-pow((x - sx) / 0.4, 2.0)))
    * exp(-max(d, 0.0) / 0.11) * smoothstep(0.15, -0.55, p.y) * smoothstep(0.0, 0.85 * max(uPad, 1.0), border)
    * (1.0 - inside) * btn * uGlow * (0.45 + 0.35 * uSurge);
  col = clamp(col + bloom, 0.0, 1.0);
  gl_FragColor = vec4(col, max(max(inside, line), max(bloom.r, max(bloom.g, bloom.b))));
}
`;

type Frame = { time: number; surge: number; front: number; glow: number; button: boolean; colors: GlowColors };

function rgb(hex: string): [number, number, number] {
  let h = hex.trim().replace(/^#/, "");
  if (h.length === 3) h = h.replace(/./g, (c) => c + c);
  const n = parseInt(h.slice(0, 6), 16);
  if (h.length < 6 || !Number.isFinite(n)) return [1, 1, 1];
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

const prefersReducedMotion = () => typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches === true;

/** Sets up the program on a canvas that covers `host` plus `pad` CSS pixels on every side. */
function createGlass(host: HTMLElement, canvas: HTMLCanvasElement, pad: number, onResize: () => void) {
  const gl = canvas.getContext("webgl", { premultipliedAlpha: true, antialias: false, alpha: true });
  if (!gl) return null;
  const compile = (type: number, src: string) => {
    const s = gl.createShader(type);
    if (!s) return null;
    gl.shaderSource(s, src);
    gl.compileShader(s);
    if (gl.getShaderParameter(s, gl.COMPILE_STATUS)) return s;
    gl.deleteShader(s);
    return null;
  };
  const vs = compile(gl.VERTEX_SHADER, VERTEX);
  const fs = compile(gl.FRAGMENT_SHADER, FRAGMENT);
  const program = gl.createProgram();
  if (!vs || !fs || !program) return null;
  gl.attachShader(program, vs);
  gl.attachShader(program, fs);
  gl.linkProgram(program);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return null;
  gl.useProgram(program);

  const buffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
  const aPos = gl.getAttribLocation(program, "aPos");
  gl.enableVertexAttribArray(aPos);
  gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0);

  const u = (name: string) => gl.getUniformLocation(program, name);
  const loc = {
    res: u("uRes"), pad: u("uPad"), time: u("uTime"), surge: u("uSurge"), front: u("uFront"), glow: u("uGlow"), button: u("uButton"),
    warm: u("uWarm"), core: u("uCore"), mid: u("uMid"), cool: u("uCool"),
  };
  const texture = gl.createTexture();
  gl.activeTexture(gl.TEXTURE0);
  gl.bindTexture(gl.TEXTURE_2D, texture);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
  gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, true);
  gl.uniform1i(u("uText"), 0);
  const clearText = () => gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 1, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE, new Uint8Array(4));
  clearText();

  let width = 0;
  let height = 0;
  let padPx = 0;
  const resize = () => {
    const box = host.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const w = Math.max(1, Math.round((box.width + 2 * pad) * dpr));
    const h = Math.max(1, Math.round((box.height + 2 * pad) * dpr));
    if (w === width && h === height) return;
    width = w;
    height = h;
    padPx = pad * dpr;
    canvas.width = w;
    canvas.height = h;
    gl.viewport(0, 0, w, h);
    onResize();
  };
  resize();
  const observer = new ResizeObserver(resize);
  observer.observe(host);

  return {
    size: () => ({ width, height, pad: padPx }),
    setText: (source: HTMLCanvasElement | null) =>
      source ? gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, source) : clearText(),
    draw: (f: Frame) => {
      gl.uniform2f(loc.res, width, height);
      gl.uniform1f(loc.pad, padPx);
      gl.uniform1f(loc.time, f.time);
      gl.uniform1f(loc.surge, f.surge);
      gl.uniform1f(loc.front, f.front);
      gl.uniform1f(loc.glow, f.glow);
      gl.uniform1f(loc.button, f.button ? 1 : 0);
      gl.uniform3fv(loc.warm, rgb(f.colors.warm));
      gl.uniform3fv(loc.core, rgb(f.colors.core));
      gl.uniform3fv(loc.mid, rgb(f.colors.mid));
      gl.uniform3fv(loc.cool, rgb(f.colors.cool));
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
    },
    dispose: () => {
      observer.disconnect();
      gl.deleteTexture(texture);
      gl.deleteBuffer(buffer);
      gl.deleteProgram(program);
      canvas.width = canvas.height = 1;
    },
  };
}

/** Runs `tick(ms)` every frame while the element is on screen and the page is visible. */
function loop(el: Element, tick: (dt: number) => void) {
  let onScreen = true;
  let stopped = false;
  let raf = 0;
  let last = performance.now();
  const frame = (now: number) => {
    raf = 0;
    const dt = Math.min(now - last, 100);
    last = now;
    tick(dt);
    wake();
  };
  function wake() {
    if (stopped || raf || !onScreen || document.hidden) return;
    last = performance.now();
    raf = requestAnimationFrame(frame);
  }
  const io = new IntersectionObserver(([entry]) => {
    onScreen = entry.isIntersecting;
    wake();
  });
  io.observe(el);
  document.addEventListener("visibilitychange", wake);
  wake();
  return () => {
    stopped = true;
    cancelAnimationFrame(raf);
    io.disconnect();
    document.removeEventListener("visibilitychange", wake);
  };
}

/** The surge over its first 640ms: a rise, then a long release. */
function surgeAt(ms: number) {
  if (ms < 0 || ms > 640) return { surge: 0, front: 0 };
  const front = ms * 0.0032;
  if (ms <= 280) return { surge: Math.pow(ms / 280, 1.8), front };
  return { surge: Math.pow(1 - (ms - 280) / 360, 1.25), front };
}

/** Which phrase is showing and how much of it is typed, `ms` after the start. */
function typed(phrases: string[], ms: number, timing: typeof GLOW_TIMING, loop: boolean) {
  const first = timing.startDelay + timing.hold;
  if (phrases.length < 2 || ms < first) return { index: 0, chars: phrases[0]?.length ?? 0, swappedAt: -Infinity };
  const steps = phrases.slice(1).map((p) => p.length * timing.typeSpeed + timing.hold);
  const cycle = steps.reduce((a, b) => a + b, 0) + (loop ? timing.typeSpeed * (phrases[0].length || 1) + timing.hold : 0);
  let rest = ms - first;
  if (loop && cycle > 0) rest %= cycle;
  else if (rest >= cycle) return { index: phrases.length - 1, chars: phrases[phrases.length - 1].length, swappedAt: -Infinity };
  const order = loop ? [...phrases.slice(1), phrases[0]] : phrases.slice(1);
  for (let i = 0; i < order.length; i++) {
    const span = order[i].length * timing.typeSpeed + timing.hold;
    if (rest < span || i === order.length - 1) {
      const index = (i + 1) % phrases.length;
      return { index, chars: Math.min(order[i].length, Math.floor(rest / timing.typeSpeed) + 1), swappedAt: ms - rest };
    }
    rest -= span;
  }
  return { index: 0, chars: phrases[0].length, swappedAt: -Infinity };
}

const fill: CSSProperties = { position: "absolute", inset: 0, width: "100%", height: "100%", borderRadius: 9999, pointerEvents: "none" };
const standIn: CSSProperties = {
  ...fill,
  background: "radial-gradient(42% 62% at 50% 106%, rgba(255,255,255,0.85), rgba(255,255,255,0) 70%), #000",
  boxShadow: "inset 0 1px 0 rgba(255,255,255,0.38), inset 0 0 0 1px rgba(255,255,255,0.12)",
};

export interface GlowPillProps {
  /** The first phrase shows at once; the rest type in, one surge per swap. */
  phrases?: string[];
  /** Width in CSS pixels; the height follows at 2.92:1. The pill never overflows its container. */
  width?: number;
  /** Colours of the pool, or one of the named palettes. */
  palette?: GlowPaletteName | Partial<GlowColors>;
  /** Strength of the resting light, 0–1.5. */
  glow?: number;
  /** Strength of the surge on each swap, 0–1.5. Zero swaps quietly. */
  surge?: number;
  /** Speed of the liquid, 1 is the reference. */
  speed?: number;
  /** Hold the liquid still; the surge still plays. */
  still?: boolean;
  /** Milliseconds per typed character. */
  typeSpeed?: number;
  /** Milliseconds each phrase stays complete. */
  hold?: number;
  startDelay?: number;
  /** Return to the first phrase after the last. */
  loop?: boolean;
  paused?: boolean;
  fontFamily?: string;
  fontWeight?: number;
  className?: string;
  style?: CSSProperties;
  "aria-label"?: string;
}

const colorsOf = (palette: GlowPillProps["palette"]): GlowColors =>
  typeof palette === "string" ? GLOW_PALETTES[palette] ?? GLOW_PALETTES.aurora : { ...GLOW_PALETTES.aurora, ...palette };

const SANS = '"Inter Variable", Inter, "SF Pro Display", -apple-system, BlinkMacSystemFont, system-ui, sans-serif';

export function GlowPill({
  phrases = ["Ask anything.", "More personal.", "More powerful."],
  width = 320,
  palette = "aurora",
  glow = 1,
  surge = 1,
  speed = 1,
  still = false,
  typeSpeed = GLOW_TIMING.typeSpeed,
  hold = GLOW_TIMING.hold,
  startDelay = GLOW_TIMING.startDelay,
  loop: repeat = true,
  paused = false,
  fontFamily = SANS,
  fontWeight = 500,
  className,
  style,
  "aria-label": label,
}: GlowPillProps) {
  const hostRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [fallback, setFallback] = useState(false);
  const live = useRef({ phrases, glow, surge, speed, still, timing: { typeSpeed, hold, startDelay }, loop: repeat, paused, colors: colorsOf(palette), font: `${fontWeight} {size}px ${fontFamily}`, dirty: true });
  useEffect(() => {
    Object.assign(live.current, { phrases, glow, surge, speed, still, timing: { typeSpeed, hold, startDelay }, loop: repeat, paused, colors: colorsOf(palette), font: `${fontWeight} {size}px ${fontFamily}`, dirty: true });
  });
  const restartKey = phrases.join("\u0000");

  useEffect(() => {
    const host = hostRef.current;
    const canvas = canvasRef.current;
    if (!host || !canvas) return;
    const s = live.current;
    const glass = createGlass(host, canvas, 0, () => (s.dirty = true));
    const text = document.createElement("canvas");
    const ctx = text.getContext("2d");
    if (!glass || !ctx) {
      setFallback(true);
      return;
    }
    const reduced = prefersReducedMotion();
    let clock = 0;
    let liquid = 0;
    let shown = "";
    let drawnFor = "";
    let settled = false;
    const stop = loop(host, (dt) => {
      if (!s.paused) {
        clock += dt;
        liquid += dt * s.speed;
      }
      const state = reduced ? { index: 0, chars: s.phrases[0]?.length ?? 0, swappedAt: -Infinity } : typed(s.phrases, clock, s.timing, s.loop);
      const phrase = (s.phrases[state.index] ?? "").slice(0, state.chars);
      const { width: w, height: h } = glass.size();
      const changed = phrase !== shown || drawnFor !== `${w}x${h}` || s.dirty;
      if (changed) {
        shown = phrase;
        drawnFor = `${w}x${h}`;
        text.width = w;
        text.height = h;
        ctx.clearRect(0, 0, w, h);
        ctx.fillStyle = "#fff";
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.font = s.font.replace("{size}", String(Math.round(h * 0.31)));
        ctx.fillText(phrase, w / 2, h / 2 + h * 0.01, w * 0.84);
        glass.setText(text);
      }
      const wave = reduced ? { surge: 0, front: 0 } : surgeAt(clock - state.swappedAt);
      const resting = reduced || s.still;
      // A still pill only redraws when its text, size, options or surge change.
      if (resting && !changed && wave.surge === 0 && settled) return;
      settled = resting && wave.surge === 0;
      glass.draw({
        time: resting ? 2.4 : liquid / 1000,
        surge: wave.surge * s.surge,
        front: wave.front,
        glow: s.glow,
        button: false,
        colors: s.colors,
      });
      s.dirty = false;
    });
    return () => {
      stop();
      glass.dispose();
    };
  }, [restartKey]);

  return (
    <div
      ref={hostRef}
      role="img"
      aria-label={label ?? phrases.join(" ")}
      className={className}
      style={{ position: "relative", width, maxWidth: "100%", aspectRatio: "2.92", borderRadius: 9999, background: "#000", isolation: "isolate", ...style }}
    >
      <canvas ref={canvasRef} aria-hidden="true" style={{ ...fill, display: fallback ? "none" : "block" }} />
      {fallback ? (
        <span
          aria-hidden="true"
          style={{ ...standIn, display: "flex", alignItems: "center", justifyContent: "center", color: "#fff", fontFamily, fontWeight, containerType: "size" }}
        >
          <span style={{ fontSize: "31cqh" }}>{phrases[0]}</span>
        </span>
      ) : null}
    </div>
  );
}

export interface GlowButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  size?: "sm" | "md";
  palette?: GlowPaletteName | Partial<GlowColors>;
  glow?: number;
  surge?: number;
  /** When the light surges: on hover and press, on press only, or never. */
  surgeOn?: "hover" | "press" | "never";
  speed?: number;
  still?: boolean;
  children?: ReactNode;
}

const SIZES = { md: { height: 36, paddingInline: 16, fontSize: 13 }, sm: { height: 32, paddingInline: 12, fontSize: 13 } };
const BLOOM = 14;

export function GlowButton({
  size = "md",
  palette = "aurora",
  glow = 1,
  surge = 1,
  surgeOn = "hover",
  speed = 1,
  still = false,
  type = "button",
  style,
  children,
  onPointerEnter,
  onPointerDown,
  onFocus,
  onBlur,
  ...rest
}: GlowButtonProps) {
  const hostRef = useRef<HTMLButtonElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [fallback, setFallback] = useState(false);
  const [ring, setRing] = useState(false);
  const live = useRef({ glow, surge, speed, still, colors: colorsOf(palette), clock: 0, surgedAt: -Infinity });
  useEffect(() => {
    Object.assign(live.current, { glow, surge, speed, still, colors: colorsOf(palette) });
  });
  const kick = () => {
    const s = live.current;
    if (s.clock - s.surgedAt > 280) s.surgedAt = s.clock;
  };

  useEffect(() => {
    const host = hostRef.current;
    const canvas = canvasRef.current;
    if (!host || !canvas) return;
    const s = live.current;
    const glass = createGlass(host, canvas, BLOOM, () => undefined);
    if (!glass) {
      setFallback(true);
      return;
    }
    const reduced = prefersReducedMotion();
    let liquid = 0;
    let drawn = "";
    const stop = loop(host, (dt) => {
      s.clock += dt;
      liquid += dt * s.speed;
      const wave = reduced ? { surge: 0, front: 0 } : surgeAt(s.clock - s.surgedAt - 240);
      const resting = reduced || s.still;
      const key = `${s.glow}|${s.surge}|${JSON.stringify(s.colors)}|${canvas.width}x${canvas.height}`;
      if (resting && wave.surge === 0 && key === drawn) return;
      drawn = resting && wave.surge === 0 ? key : "";
      glass.draw({ time: resting ? 2.4 : liquid / 1000, surge: wave.surge * s.surge, front: wave.front, glow: s.glow, button: true, colors: s.colors });
    });
    return () => {
      stop();
      glass.dispose();
    };
  }, []);

  return (
    <button
      ref={hostRef}
      type={type}
      {...rest}
      onPointerEnter={(e) => {
        if (surgeOn === "hover") kick();
        onPointerEnter?.(e);
      }}
      onPointerDown={(e) => {
        if (surgeOn !== "never") kick();
        onPointerDown?.(e);
      }}
      onFocus={(e) => {
        setRing(e.currentTarget.matches(":focus-visible"));
        onFocus?.(e);
      }}
      onBlur={(e) => {
        setRing(false);
        onBlur?.(e);
      }}
      style={{
        position: "relative",
        isolation: "isolate",
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        boxSizing: "border-box",
        border: 0,
        margin: 0,
        borderRadius: 9999,
        background: "#000",
        color: "#fff",
        fontFamily: "inherit",
        fontWeight: 500,
        letterSpacing: "-0.01em",
        lineHeight: 1,
        whiteSpace: "nowrap",
        cursor: "pointer",
        outline: ring ? "2px solid rgba(255,255,255,0.55)" : "none",
        outlineOffset: 2,
        ...SIZES[size],
        ...style,
      }}
    >
      <canvas
        ref={canvasRef}
        aria-hidden="true"
        style={{ ...fill, inset: -BLOOM, width: `calc(100% + ${2 * BLOOM}px)`, height: `calc(100% + ${2 * BLOOM}px)`, borderRadius: 0, zIndex: -1, display: fallback ? "none" : "block" }}
      />
      {fallback ? <span aria-hidden="true" style={{ ...standIn, zIndex: -1 }} /> : null}
      {children}
    </button>
  );
}
